This is an interface of a Contract content. Example: Blog, Photo v.v...A Contract content always has user_id, user_type, owner_id, and owner_type.
namespace MetaFox\Platform\Contracts;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\MorphTo;
use Illuminate\Support\Collection;
interface Content extends Entity
{
    /**
     * @return int
     */
    public function userId(): int;
    /**
     * @return string
     */
    public function userType(): string;
    /**
     * @return int
     */
    public function ownerId(): int;
    /**
     * @return string
     */
    public function ownerType(): string;
    /**
     * @return User|MorphTo
     */
    public function user();
    /**
     * @return UserEntity|BelongsTo
     */
    public function userEntity();
    /**
     * @return User|MorphTo
     */
    public function owner();
    /**
     * @return UserEntity|BelongsTo
     */
    public function ownerEntity();
}

