    public function testCreateBlog($fn, $assertion)
    {
        $data = is_callable($fn) ? $fn() : $fn;
        $guards = ['userId', 'ownerId'];
        extract(Arr::only($data, $guards));
        $attributes = Arr::except($data, $guards);
