            value={item.is_draft && tab !== 'draft'}
            variant="h4"
            component="span"
          />
          <Tooltip title={item.title} arrow>
            <Link to={item.link} identityTracking={identity}>
              {item.title}
            </Link>
          </Tooltip>
        </ItemTitleStyled>
        {itemProps.showActionMenu ? (
          <ItemAction
            placement={isMobile ? 'bottom-end' : 'top-end'}
            spacing="normal"
          >
            <ItemActionMenu
              identity={identity}
              icon={'ico-dottedmore-vertical-o'}
              state={state}
              handleAction={handleAction}
            />
          </ItemAction>
        ) : null}
        {item.description ? (
          <ItemSummary sx={{ my: 1 }}>
            <HtmlViewer html={item.description} simpleTransform />
          </ItemSummary>
        ) : null}
        <ItemSubInfo sx={{ color: 'text.secondary' }}>
          <UserName color="inherit" to={user.link} user={user} />
          <FormatDate
            data-testid="creationDate"
            value={creation_date}
            format="ll"
          />
          <Statistic
            values={item.statistic}
            display={'total_view'}
            component={'span'}
            skipZero={false}
          />
        </ItemSubInfo>
      </ItemText>
    </ItemView>
  );
};
export default BlogItemView;

